import { describe, test } from 'node:test'
import assert from 'node:assert/strict'
import DUT from '@/cloud/devices/F3M2CYK__'
import type { Metadata } from '@/cloud/thinq'
import { MockHAConnection, MockThinq2Device, buf, captureLog } from '@/tests/helpers/mocks'

const DEVICE_ID = 'test-id'
const MODEL_ID = 'F3M2CYK__'
const META: Metadata = { modelId: MODEL_ID, modelName: 'F3M2CYK__', swVersion: '0.0.0' }

// This washer's real traffic is 0xCD (idle keepalive, ~409 bytes) and 0xBD (event, ~410-480 bytes) —
// it never sends the 0xEC/0xEB frames the handler was originally written for (see the comment above
// processAABB in the source file). All 0xCD/0xBD fixtures below are REAL frames taken verbatim from a
// ~2-day capture of the physical appliance (device 826dbe82-...), spanning one Warm/High/TurboWash
// load (total 53 min) and a second load (total 18 min, no Washing phase), plus a third
// capture of a Tub Clean (total 1:29) that showed the time fields are [hour][minute] pairs.

// ── 0xCD (idle keepalive) — first load, Normal/Warm/High spin/Normal soil/TurboWash, total 53 min ─────────────────────────

const CD_WASHING = buf(
    '',
)
const CD_RINSING = buf(
    '',
)
const CD_SPINNING = buf(
    '',
)
const CD_COMPLETE = buf(
    '',
)

// Second load (18 min, course not recorded): total=remaining=18, phase goes straight to Rinsing — no Washing phase
// (matches the physical panel for that course).
const CD_SECOND_LOAD_RINSING = buf(
    '',
)

// ── 0xBD (event, sent on phase/state changes) ────────────────────────────────────────────────────────

const BD_SELECTING = buf(
    '',
)
const BD_SENSING = buf(
    '',
)
const BD_WASHING = buf(
    '',
)
const BD_RINSING = buf(
    '',
)
// The 476-byte-body variant seen while spinning (larger than the usual ~406) — must decode the same way.
const BD_SPINNING_LARGE = buf(
    '',
)

// Second load (18 min), at the Selecting step just before start: total already committed to 18.
const BD_SECOND_LOAD_SELECTING = buf(
    '',
)

// A real 0xEB single-record frame for this same washer model family (F3L2CYU__, offsets identical) —
// this washer never actually sends these, but the dispatcher must still route them correctly.
const EB_RECONNECT_IDLE = buf('aa2020eb001805000000000000000000000000000000000000003318000068bb')

// Frames too short to hold phase/remaining/total — must be ignored without throwing.
const CD_TOO_SHORT = buf('AA0620CD000102BB')
const BD_TOO_SHORT = buf('AA0620BD000102BB')

// Same as CD_WASHING but with the class byte changed from 0x20 (washer) to 0x30 (dryer) — must be
// ignored.
const CD_WRONG_CLASS = buf(CD_WASHING.toString('hex').replace(/^aa0020/i, 'aa0030'))

// ── Third capture: Tub Clean (course 0x0d), 1:29 total, washes-since-Tub-Clean = 8 ─────────────────

const TC_BD_SELECTING = buf(
    '',
)
// 1:23 remaining of 1:29 — a uint16 read would give 279/285.
const TC_CD_WASHING = buf(
    '',
)
// Crossed the hour boundary: 00 3a = 58 min remaining.
const TC_CD_WASHING_UNDER_HOUR = buf(
    '',
)
// End-of-cycle 0xBD (event byte 0x03), still reporting Spinning with 0:01 left.
const TC_BD_CYCLE_END = buf(
    '',
)

// 0x72 heartbeats around the Tub Clean: C9 at start, transient 00 then C8 at the end.
const HB_START = buf('AA09207200C9005BBB')
const HB_TRANSIENT_ZERO = buf('AA09207200000010BB')
const HB_STOP = buf('AA09207200C80058BB')

// 0xD8 washes-since-Tub-Clean bursts: power-on placeholder 00, then the real count; after a load the
// updated count; after the Tub Clean, 00.
const COUNT_POWER_ON_PLACEHOLDER = buf('AA0720D800FCBB')
const COUNT_8 = buf('AA0720D808E4BB')
const COUNT_7_AFTER_LOAD = buf('AA0720D807E5BB')
const COUNT_RESET_AFTER_TUB_CLEAN = buf('AA0720D800FCBB')

// ── Fourth capture: Towels (course 0x0e), 2026-09-23 ───────────────────────────────────────────────

// Selecting, 1:01 estimate, washes-since-Tub-Clean = 0.
const TOWELS_BD_SELECTING = buf(
    '',
)
// Cycle end, in this order: 72 00, then the updated count (01), then the end-of-cycle 0xBD still
// carrying the pre-cycle count (00) — the reverse of the Tub Clean's order.
const TOWELS_HB_CYCLE_ENDING = buf('AA09207200000010BB')
const TOWELS_COUNT_1 = buf('AA0720D801FFBB')
const TOWELS_BD_CYCLE_END = buf(
    '',
)
// Next power-on, 40 minutes later: placeholder 00 burst.
const TOWELS_NEXT_POWER_ON_PLACEHOLDER = buf('AA0720D800FCBB')

// ── Fifth capture: Heavy Duty (course 0x07), 2026-09-23 21:46Z, panel photo: Heavy Duty, Cold,
// Medium spin, Light soil, 1:44 ─────────────────────────────────────────────────────────────────────

const HEAVY_DUTY_BD_SELECTING = buf(
    '',
)

// ── Sixth capture: Sanitary (course 0x02), 2026-09-23 23:11Z, panel photo: Sanitary, Extra Hot,
// High spin, Normal soil, Steam and TurboWash off ─────────────────────────────────────────────────

// Washing, 1:48 left of 1:50.
const SANITARY_CD_WASHING = buf(
    '',
)

// ── Seventh capture: Rinse+Spin (course 0x10), 2026-09-23 23:25Z, panel photo: Rinse+Spin, 0:18, Cold,
// High spin, no soil, TurboWash off ──────────────────────────────────────────────────────────────────

const RINSE_SPIN_BD_SELECTING = buf(
    '',
)

// ── Eighth capture: Allergiene (course 0x03), 2026-09-23 23:48Z, panel photo: Allergiene, Steam and
// Delay Wash lit (display 1:00), TurboWash and Extra Rinse off, High spin, detergent 2 bars ──────────

// Selected with a 1:00 delay: options 0x06 (Steam + Delay), delay time 01 00.
const ALLERGIENE_BD_DELAY_SET = buf(
    '',
)
// Four minutes later: phase 0x0a (Delay Wash), delay counting down (00 39 = 0:57).
const ALLERGIENE_CD_DELAY_WAITING = buf(
    '',
)

// The delay ran out: still phase 0x0a for a moment, delay time 00 00, options 0x04 (Delay bit cleared).
const ALLERGIENE_BD_DELAY_OVER = buf(
    '',
)

// ── Ninth capture: Bright Whites (course 0x08), 2026-09-24 05:02Z, panel photo: Bright Whites, Hot,
// Extra High, Heavy soil, TurboWash and Extra Rinse lit, detergent 1 bar ──────────────────────────────

const BRIGHT_WHITES_BD_SELECTING = buf(
    '',
)

// ── Tenth capture: Delicates (course 0x0a), 2026-09-24 05:09Z, panel photo: Delicates, Tap Cold, Low
// spin, Light-Normal soil, Pre-wash lit, TurboWash off ─────────────────────────────────────────────────

const DELICATES_BD_SELECTING = buf(
    '',
)

// ── Eleventh capture: Perm. Press (course 0x05), 2026-09-24 05:17Z, panel photo: Perm. Press, Tap Cold,
// Medium, Normal-Heavy soil, TurboWash lit, detergent 3 bars, softener 2 bars + Refill, Signal on ────

const PERM_PRESS_BD_SENSING = buf(
    '',
)

// ── 2026-09-24 05:46Z: the Downloaded dial position (reports course 0x06, same as Normal), Cold, Low,
// Normal soil, Fresh Care lamp lit ─────────────────────────────────────────────────────────────────────

const DOWNLOADED_BD_SELECTING = buf(
    '',
)

// ── 2026-09-24 05:55Z: Sportswear (course 0x13), Warm, Medium, Normal soil, Extra Rinse x2, Fresh Care
// lamp still lit, detergent 1 bar ────────────────────────────────────────────────────────────────────

const SPORTSWEAR_BD_SELECTING = buf(
    '',
)

// ── 2026-09-24 20:19Z: Towels (course 0x0e), Cold, Extra High, Normal soil, Cold Wash lamp lit ─────────

const TOWELS_COLD_WASH_BD_SELECTING = buf(
    '',
)

// ── 2026-09-24 17:29Z: Speed Wash (course 0x0c), 0:07, No Spin, Cold, Light soil ──────────────────────

const SPEED_WASH_BD_SELECTING = buf(
    '',
)

// ── 2026-09-24 17:52Z: Bedding (course 0x04), 1:00, Warm, Medium, Normal soil; Control Lock engaged
// after start and released ~5 minutes later ──────────────────────────────────────────────────────────

const BEDDING_BD_SELECTING = buf(
    '',
)
// Report taken while Control Lock was on: options 0x01.
const BEDDING_CD_LOCKED = buf(
    '',
)
// Next report, after it was released: options 0x00.
const BEDDING_CD_UNLOCKED = buf(
    '',
)

// ── 2026-09-24 23:59Z: Downloaded dial (course 0x06), Warm, Low, TurboWash, Fresh Care off; detergent
// 2 bars, softener at max (3 bars), no Refill warning (panel photo) ─────────────────────────────────

const DOWNLOADED_SOFTENER_MAX_BD_SELECTING = buf(
    '',
)

// 2026-09-25 00:16Z: Perm. Press with the softener set to one bar, detergent 3 bars.
const SOFTENER_ONE_BAR_BD_SELECTING = buf(
    '',
)

// 2026-09-25 00:31Z: Rinse+Spin paused one second after Start — phase 0x06 in the next 0xCD.
const RINSE_SPIN_CD_PAUSED = buf(
    '',
)

// 0x7F sensed-load frames: 0x40 on the first (full) Normal load, 0x13 with a single washcloth.
const LOAD_FULL = buf('AA09207F010040C6BB')
const LOAD_WASHCLOTH = buf('AA09207F01001333BB')

// Real 0x31 serial/identity frame, sent once per reconnect — not decoded.
const SERIAL = buf(
    'AA372031020153414134303438343330320000F54F00008000000000000253414134303438343230320000B371000040000007C00054BB',
)

function makeDevice() {
    const ha = new MockHAConnection()
    const thinq = new MockThinq2Device(DEVICE_ID, META)
    const dev = new DUT(ha.asConnection(), thinq, META)
    return { ha, thinq, dev }
}

describe(MODEL_ID, () => {
    test('config exposes remaining_time and a separate initial_time, both plain-minute durations', () => {
        const { ha } = makeDevice()
        const cfg = ha.devices[DEVICE_ID].config
        assert.ok(cfg, 'config published on construction')
        const components = cfg!.components as Record<string, Record<string, unknown>>
        for (const c of [
            'remaining_time',
            'initial_time',
            'power',
            'status',
            'course',
            'tub_clean_count',
            'soil',
            'spin',
            'temp',
            'turbo_wash',
            'steam',
            'delay_wash',
            'reserve_time',
            'detergent_level',
            'extra_rinse',
            'pre_wash',
            'extra_rinse_count',
            'fresh_care',
            'cold_wash',
            'control_lock',
            'softener_level',
            'softener_refill',
            'load_size',
        ]) {
            assert.ok(components[c], `component ${c} present`)
        }
        // 0xEC/0xEB-only fields this model never sends must not be advertised (they'd sit at Unknown)
        for (const c of ['door', 'door_lock']) {
            assert.equal(components[c], undefined, `component ${c} absent`)
        }
        assert.equal(components.initial_time.device_class, 'duration')
        assert.equal(components.initial_time.unit_of_measurement, 'min')
    })

    test('0xCD frames decode phase/power/remaining/initial across a full wash cycle (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        for (const [frame, status, power, remaining, initial] of [
            [CD_WASHING, 'Washing', 'ON', 49, 53],
            [CD_RINSING, 'Rinsing', 'ON', 29, 53],
            [CD_SPINNING, 'Spinning', 'ON', 13, 53],
            // post-cycle frame zeroes the total; the last known total is kept
            [CD_COMPLETE, 'Complete', 'OFF', 0, 53],
        ] as const) {
            thinq.emit('data', frame)
            assert.equal(p.status, status)
            assert.equal(p.power, power)
            assert.equal(p.remaining_time, remaining)
            assert.equal(p.initial_time, initial)
        }
        assert.equal(p.tub_clean_count, 7) // incremented from 6 at the end of the load
    })

    test('0xCD second load goes straight to Rinsing with total=remaining=18 (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_SECOND_LOAD_RINSING)
        const p = ha.devices[DEVICE_ID].properties
        assert.equal(p.status, 'Rinsing')
        assert.equal(p.remaining_time, 14)
        assert.equal(p.initial_time, 18)
    })

    test('0xBD frames decode phase/power/remaining/initial across a full wash cycle (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        for (const [frame, status, power, remaining, initial] of [
            [BD_SELECTING, 'Selecting', 'ON', 1, 0],
            [BD_SENSING, 'Sensing', 'ON', 46, 46],
            [BD_WASHING, 'Washing', 'ON', 33, 53],
            [BD_RINSING, 'Rinsing', 'ON', 18, 53],
            // the 476-byte end-of-cycle 0xBD (event byte 0x03) still says Spinning, 0:01 left
            [BD_SPINNING_LARGE, 'Complete', 'OFF', 0, 53],
        ] as const) {
            thinq.emit('data', frame)
            assert.equal(p.status, status)
            assert.equal(p.power, power)
            assert.equal(p.remaining_time, remaining)
            assert.equal(p.initial_time, initial)
        }
        assert.equal(p.course, 'Normal')
        assert.equal(p.tub_clean_count, 6)
    })

    test('0xBD second load Selecting reports total already committed to 18 (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', BD_SECOND_LOAD_SELECTING)
        const p = ha.devices[DEVICE_ID].properties
        assert.equal(p.status, 'Selecting')
        assert.equal(p.remaining_time, 18)
        assert.equal(p.initial_time, 18)
        assert.equal(p.course, 'Rinse+Spin')
    })

    test('Tub Clean: times are [hour][minute] pairs, course and tub-clean count decode (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        thinq.emit('data', TC_BD_SELECTING)
        assert.equal(p.status, 'Selecting')
        assert.equal(p.course, 'Tub Clean')
        assert.equal(p.initial_time, 89)
        assert.equal(p.tub_clean_count, 8)

        thinq.emit('data', TC_CD_WASHING)
        assert.equal(p.status, 'Washing')
        assert.equal(p.remaining_time, 83)
        assert.equal(p.initial_time, 89)

        thinq.emit('data', TC_CD_WASHING_UNDER_HOUR)
        assert.equal(p.remaining_time, 58)

        thinq.emit('data', TC_BD_CYCLE_END)
        assert.equal(p.status, 'Complete')
        assert.equal(p.power, 'OFF')
        assert.equal(p.remaining_time, 0)
        assert.equal(p.initial_time, 89)
    })

    test('0x72 heartbeat drives power: C9 ON, C8 OFF, transient 00 ignored (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', HB_START)
        assert.equal(p.power, 'ON')
        thinq.emit('data', HB_TRANSIENT_ZERO)
        assert.equal(p.power, 'ON')
        thinq.emit('data', HB_STOP)
        assert.equal(p.power, 'OFF')
    })

    test('the pre-existing 0xEB/0xEC dispatch still works after adding 0xCD/0xBD (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', EB_RECONNECT_IDLE)
        const props = ha.devices[DEVICE_ID].properties
        assert.equal(props.status, 'Selecting')
        assert.equal(props.power, 'ON')
    })

    test('0xD8 count: power-on 00 ignored, reset to 0 after a Tub Clean (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        // power-on: placeholder 00 burst, then the real count
        thinq.emit('data', COUNT_POWER_ON_PLACEHOLDER)
        assert.equal(p.tub_clean_count, undefined)
        thinq.emit('data', COUNT_8)
        assert.equal(p.tub_clean_count, 8)
        thinq.emit('data', COUNT_POWER_ON_PLACEHOLDER)
        assert.equal(p.tub_clean_count, 8)

        // Tub Clean ends: 72 00, then the end-of-cycle 0xBD (stale pre-cycle 8, not published), then
        // the 0xD8 reset
        thinq.emit('data', HB_TRANSIENT_ZERO)
        thinq.emit('data', TC_BD_CYCLE_END)
        assert.equal(p.tub_clean_count, 8)
        thinq.emit('data', COUNT_RESET_AFTER_TUB_CLEAN)
        assert.equal(p.tub_clean_count, 0)
        // the rest of the burst, and later power-on placeholders, don't disturb it
        thinq.emit('data', COUNT_RESET_AFTER_TUB_CLEAN)
        assert.equal(p.tub_clean_count, 0)
    })

    test('0xD8 count after an ordinary load carries the incremented value (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', BD_WASHING) // load 1, count 6 at start
        assert.equal(ha.devices[DEVICE_ID].properties.tub_clean_count, 6)
        thinq.emit('data', BD_SPINNING_LARGE) // end-of-cycle 0xBD: stale count, not published
        thinq.emit('data', COUNT_7_AFTER_LOAD)
        assert.equal(ha.devices[DEVICE_ID].properties.tub_clean_count, 7)
    })

    test('Towels: course decodes, count survives the updated 0xD8 arriving before the end-of-cycle 0xBD', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        thinq.emit('data', TOWELS_BD_SELECTING)
        assert.equal(p.course, 'Towels')
        assert.equal(p.initial_time, 61)
        assert.equal(p.tub_clean_count, 0)

        thinq.emit('data', TOWELS_HB_CYCLE_ENDING)
        thinq.emit('data', TOWELS_COUNT_1)
        assert.equal(p.tub_clean_count, 1)
        thinq.emit('data', TOWELS_BD_CYCLE_END)
        assert.equal(p.status, 'Complete')
        assert.equal(p.tub_clean_count, 1) // previously overwritten with the stale 0
        thinq.emit('data', TOWELS_NEXT_POWER_ON_PLACEHOLDER)
        assert.equal(p.tub_clean_count, 1)
    })

    test('Heavy Duty: course and 1:44 estimate decode from the selecting 0xBD', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', HEAVY_DUTY_BD_SELECTING)
        assert.equal(p.course, 'Heavy Duty')
        assert.equal(p.status, 'Selecting')
        assert.equal(p.initial_time, 104)
        assert.equal(p.remaining_time, 104)
        assert.equal(p.tub_clean_count, 2)
        assert.equal(p.soil, 'Light')
        assert.equal(p.temp, 'Cold')
        assert.equal(p.spin, 'Medium')
    })

    test('Sanitary: course and Extra Hot decode against the panel photo (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', SANITARY_CD_WASHING)
        assert.equal(p.course, 'Sanitary')
        assert.equal(p.status, 'Washing')
        assert.equal(p.remaining_time, 108)
        assert.equal(p.initial_time, 110)
        assert.equal(p.temp, 'Extra Hot')
        assert.equal(p.spin, 'High')
        assert.equal(p.soil, 'Normal')
        assert.equal(p.tub_clean_count, 3)
    })

    test('Rinse+Spin: course, 0:18, Cold and High decode against the panel photo (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', RINSE_SPIN_BD_SELECTING)
        assert.equal(p.course, 'Rinse+Spin')
        assert.equal(p.status, 'Selecting')
        assert.equal(p.initial_time, 18)
        assert.equal(p.temp, 'Cold')
        assert.equal(p.spin, 'High')
        assert.equal(p.soil, '-') // Rinse+Spin has no soil setting
    })

    test('Steam stays ON after the Tub Clean clears the bit at rinse (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', TC_BD_SELECTING)
        assert.equal(p.steam, 'ON')
        thinq.emit('data', TC_CD_WASHING_UNDER_HOUR)
        assert.equal(p.steam, 'ON')
    })

    test('Allergiene with Delay Wash: options, delay countdown and Delay Wash phase (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        thinq.emit('data', ALLERGIENE_BD_DELAY_SET)
        assert.equal(p.course, 'Allergiene')
        assert.equal(p.steam, 'ON')
        assert.equal(p.delay_wash, 'ON')
        assert.equal(p.turbo_wash, 'OFF')
        assert.equal(p.reserve_time, 60)
        assert.equal(p.detergent_level, 'Normal')

        thinq.emit('data', ALLERGIENE_CD_DELAY_WAITING)
        assert.equal(p.status, 'Delay Wash')
        assert.equal(p.reserve_time, 57)
        assert.equal(p.delay_wash, 'ON')

        // Delay is a live state: it clears when the delay runs out, while Steam is held
        thinq.emit('data', ALLERGIENE_BD_DELAY_OVER)
        assert.equal(p.reserve_time, 0)
        assert.equal(p.delay_wash, 'OFF')
        assert.equal(p.steam, 'ON')
    })

    test('TurboWash, Steam and detergent level match the other panel photos (real captures)', () => {
        const cases = [
            // frame, turbo_wash, steam, detergent_level (bars in the photo)
            [CD_WASHING, 'ON', 'OFF', 'More'], // Normal, 09-21: TurboWash lit, 3 bars
            [HEAVY_DUTY_BD_SELECTING, 'ON', 'OFF', 'More'], // Heavy Duty: TurboWash lit, 3 bars
            [SANITARY_CD_WASHING, 'OFF', 'OFF', 'Normal'], // Sanitary: both off, 2 bars
            [RINSE_SPIN_BD_SELECTING, 'OFF', 'OFF', 'Off'], // Rinse+Spin: both off, no bars
            [TC_CD_WASHING, 'OFF', 'ON', 'Off'], // Tub Clean: Steam lit, doesn't dispense
        ] as const
        for (const [frame, turbo, steam, detergent] of cases) {
            const { ha, thinq } = makeDevice()
            const p = ha.devices[DEVICE_ID].properties
            thinq.emit('data', RINSE_SPIN_BD_SELECTING) // selecting, all options off: sets the baseline
            thinq.emit('data', frame)
            assert.equal(p.turbo_wash, turbo)
            assert.equal(p.steam, steam)
            assert.equal(p.delay_wash, 'OFF')
            assert.equal(p.reserve_time, 0)
            assert.equal(p.detergent_level, detergent)
        }
    })

    test('Bright Whites: Hot, Extra High, Heavy, Extra Rinse and one detergent bar (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', BRIGHT_WHITES_BD_SELECTING)
        assert.equal(p.course, 'Bright Whites')
        assert.equal(p.initial_time, 59)
        assert.equal(p.temp, 'Hot')
        assert.equal(p.spin, 'Extra High')
        assert.equal(p.soil, 'Heavy')
        assert.equal(p.turbo_wash, 'ON')
        assert.equal(p.extra_rinse, 'ON')
        assert.equal(p.steam, 'OFF')
        assert.equal(p.detergent_level, 'Less')
    })

    test('Delicates: Tap Cold, Low, Light-Normal soil and Pre-wash (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', DELICATES_BD_SELECTING)
        assert.equal(p.course, 'Delicates')
        assert.equal(p.initial_time, 53)
        assert.equal(p.temp, 'Tap Cold')
        assert.equal(p.spin, 'Low')
        assert.equal(p.soil, 'Light-Normal')
        assert.equal(p.pre_wash, 'ON')
        assert.equal(p.turbo_wash, 'OFF')
        assert.equal(p.extra_rinse, 'OFF')
    })

    test('Perm. Press: Tap Cold, Medium, Normal-Heavy soil, detergent More (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', PERM_PRESS_BD_SENSING)
        assert.equal(p.course, 'Perm. Press')
        assert.equal(p.temp, 'Tap Cold')
        assert.equal(p.spin, 'Medium')
        assert.equal(p.soil, 'Normal-Heavy')
        assert.equal(p.turbo_wash, 'ON')
        // the detergent byte also carries new low bits here (0x26 vs 0x02 on every other load) — see
        // DUMP_DETERGENT_MASK; they don't disturb the level
        assert.equal(p.detergent_level, 'More')
    })

    test('Sportswear: Extra Rinse x2 and Fresh Care (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', SPORTSWEAR_BD_SELECTING)
        assert.equal(p.course, 'Sportswear')
        assert.equal(p.temp, 'Warm')
        assert.equal(p.spin, 'Medium')
        assert.equal(p.soil, 'Normal')
        assert.equal(p.extra_rinse, 'ON')
        assert.equal(p.extra_rinse_count, 2)
        assert.equal(p.fresh_care, 'ON')
        assert.equal(p.detergent_level, 'Less')
    })

    test('Fresh Care and Extra Rinse count read from the other photographed loads (real captures)', () => {
        for (const [frame, freshCare, extraRinses] of [
            [DOWNLOADED_BD_SELECTING, 'ON', 0], // Fresh Care lamp lit
            [BRIGHT_WHITES_BD_SELECTING, 'OFF', 1], // one extra rinse
            [DELICATES_BD_SELECTING, 'OFF', 0],
        ] as const) {
            const { ha, thinq } = makeDevice()
            thinq.emit('data', frame)
            assert.equal(ha.devices[DEVICE_ID].properties.fresh_care, freshCare)
            assert.equal(ha.devices[DEVICE_ID].properties.extra_rinse_count, extraRinses)
        }
    })

    test('Towels with Cold Wash (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', TOWELS_COLD_WASH_BD_SELECTING)
        assert.equal(p.course, 'Towels')
        assert.equal(p.temp, 'Cold')
        assert.equal(p.spin, 'Extra High')
        assert.equal(p.soil, 'Normal')
        assert.equal(p.cold_wash, 'ON')
        assert.equal(p.fresh_care, 'OFF')
    })

    test('Cold Wash reads OFF on Cold-temp loads without it (real captures)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', SPEED_WASH_BD_SELECTING) // Cold temp, Cold Wash lamp off in the panel photo
        assert.equal(ha.devices[DEVICE_ID].properties.temp, 'Cold')
        assert.equal(ha.devices[DEVICE_ID].properties.cold_wash, 'OFF')
    })

    test('Speed Wash: No Spin, Cold, Light soil (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', SPEED_WASH_BD_SELECTING)
        assert.equal(p.course, 'Speed Wash')
        assert.equal(p.initial_time, 7)
        assert.equal(p.spin, 'No Spin')
        assert.equal(p.temp, 'Cold')
        assert.equal(p.soil, 'Light')
    })

    test('Bedding: course decodes, and Control Lock follows the options bit (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', BEDDING_BD_SELECTING)
        assert.equal(p.course, 'Bedding')
        assert.equal(p.initial_time, 60)
        assert.equal(p.control_lock, 'OFF')

        thinq.emit('data', BEDDING_CD_LOCKED)
        assert.equal(p.control_lock, 'ON')
        assert.equal(p.status, 'Washing')

        thinq.emit('data', BEDDING_CD_UNLOCKED)
        assert.equal(p.control_lock, 'OFF')
    })

    test('a paused cycle reports phase 0x06 and stays powered (real capture)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', RINSE_SPIN_CD_PAUSED)
        assert.equal(p.status, 'Paused')
        assert.equal(p.power, 'ON')
        assert.equal(p.course, 'Rinse+Spin')
        assert.equal(p.remaining_time, 18)
    })

    test('softener level and Refill warning match the panel photos (real captures)', () => {
        for (const [frame, detergent, softener, refill] of [
            [DOWNLOADED_SOFTENER_MAX_BD_SELECTING, 'Normal', 'More', 'OFF'], // 2 + 3 bars, tank full
            [PERM_PRESS_BD_SENSING, 'More', 'Normal', 'ON'], // 3 + 2 bars, red Refill lit
            [DELICATES_BD_SELECTING, 'Less', 'Off', 'OFF'], // softener bars dark
            [SOFTENER_ONE_BAR_BD_SELECTING, 'More', 'Less', 'OFF'], // softener set to one bar
        ] as const) {
            const { ha, thinq } = makeDevice()
            thinq.emit('data', frame)
            const p = ha.devices[DEVICE_ID].properties
            assert.equal(p.detergent_level, detergent)
            assert.equal(p.softener_level, softener)
            assert.equal(p.softener_refill, refill)
        }
    })

    test('soil/temp/spin decode against the load 1 panel photo and hold once their stage has cleared them', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', BD_SELECTING) // no course committed yet: all zero, nothing published
        assert.equal(p.soil, undefined)
        thinq.emit('data', BD_SENSING)
        assert.deepEqual([p.soil, p.temp, p.spin], ['Normal', 'Warm', 'High'])
        thinq.emit('data', CD_RINSING) // soil byte cleared once rinsing starts
        assert.deepEqual([p.soil, p.temp, p.spin], ['Normal', 'Warm', 'High'])
        thinq.emit('data', CD_SPINNING) // temp byte cleared once spinning starts
        assert.deepEqual([p.soil, p.temp, p.spin], ['Normal', 'Warm', 'High'])
    })

    test('settings a course does not use publish as "-" at selection', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties
        thinq.emit('data', BD_SENSING)
        thinq.emit('data', TC_BD_SELECTING) // Tub Clean: no soil or temp
        assert.deepEqual([p.soil, p.temp, p.spin], ['-', '-', 'Medium'])
        thinq.emit('data', BD_SECOND_LOAD_SELECTING) // Rinse+Spin-like 18-min load: no soil
        assert.deepEqual([p.soil, p.temp, p.spin], ['-', 'Cold', 'High'])
        thinq.emit('data', TOWELS_BD_SELECTING)
        assert.deepEqual([p.soil, p.temp, p.spin], ['Normal', 'Warm', 'Extra High'])
    })

    // ── Ignored packet tests ──────────────────────────────────────────────────

    test('0xCD/0xBD frames too short to hold phase/remaining/initial are ignored', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_TOO_SHORT)
        thinq.emit('data', BD_TOO_SHORT)
        assert.equal(ha.devices[DEVICE_ID].properties.status, undefined)
    })

    test('frames with wrong device class byte (not 0x20) are ignored', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_WRONG_CLASS)
        assert.equal(ha.devices[DEVICE_ID].properties.status, undefined)
    })

    // ── Logging (for future status-code hunting) ────────────────────────────────

    test('0x7F publishes the sensed load size (real captures)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', LOAD_FULL)
        assert.equal(ha.devices[DEVICE_ID].properties.load_size, 0x40)
        thinq.emit('data', LOAD_WASHCLOTH)
        assert.equal(ha.devices[DEVICE_ID].properties.load_size, 0x13)
    })

    test('undecoded frame types (0x31 serial) are logged; 0xD8 and 0x7F are not (real captures)', () => {
        const { thinq } = makeDevice()
        const cap = captureLog()
        try {
            thinq.emit('data', COUNT_POWER_ON_PLACEHOLDER)
            thinq.emit('data', LOAD_FULL)
            thinq.emit('data', SERIAL)
            assert.equal(cap.calls.length, 1)
            for (const call of cap.calls) {
                const [, topic, message] = call.arguments
                assert.equal(topic, 'F3M2CYK__')
                assert.equal(message, 'unrecognized frame')
            }
            assert.equal(cap.calls[0].arguments[3], SERIAL.subarray(2, -2).toString('hex'))
        } finally {
            cap.restore()
        }
    })
})
